def maximalPathQuality(values: list[int], edges: list[list[int]], maxTime: int) -> int:
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, t in edges:
        graph[u].append((v, t))
        graph[v].append((u, t))
    visited = defaultdict(int)
    visited[0] = 1
    ans = [values[0]]
    def dfs(u, time_left, curr_val):
        if u == 0:
            ans[0] = max(ans[0], curr_val)
        for v, t in graph[u]:
            if time_left >= t:
                first_visit = (visited[v] == 0)
                visited[v] += 1
                dfs(v, time_left - t, curr_val + (values[v] if first_visit else 0))
                visited[v] -= 1
    dfs(0, maxTime, values[0])
    return ans[0]

